            {
                var reverseHand = HandCard.Where(x => x != null).Reverse().ToList();
                int changed = 0; for (int i = 0; i < reverseHand.Count && changed < transformCount; i++)
                {
                    var target = reverseHand[i]; if (target?.data == null) { continue; }
                    if (target.data["Id"].StartsWith("ReturnAgain_")||(CardGetEnch(target.dataConfig)!=null&&CardGetEnch(target.dataConfig).data["Id"]==DataId.Crowdfundingenchtag_19))
                    { continue; }
                    string toId;
                    if (level == 100) { toId = DataId.ReturnAgain_13; }
